python3 -c '
from sgf_parsing import parse, SgfTree

# Test nested variations on a chain with valid property values:
t4 = parse("(;A[a];B[b];C[c](;D[d];E[e])(;F[f];G[g]))")
assert t4.properties == {"A": ["a"]}
b = t4.children[0]
assert b.properties == {"B": ["b"]}
c = b.children[0]
assert c.properties == {"C": ["c"]}
assert len(c.children) == 2
d = c.children[0]
assert d.properties == {"D": ["d"]}
assert d.children[0].properties == {"E": ["e"]}
f = c.children[1]
assert f.properties == {"F": ["f"]}
assert f.children[0].properties == {"G": ["g"]}

# Test nodes without properties in variations:
t4b = parse("(;(;))")
# Wait, can a variation have empty node?
assert t4b.properties == {}
assert len(t4b.children) == 1
assert t4b.children[0].properties == {}

print("Valid variations passed!")
'

python3 -c '
from sgf_parsing import parse, SgfTree

t1 = parse("(;A[foo;bar])")
assert t1.properties == {"A": ["foo;bar"]}

t2 = parse("(;A[foo(bar)baz])")
assert t2.properties == {"A": ["foo(bar)baz"]}

t3 = parse("(;A[foo[bar])")
assert t3.properties == {"A": ["foo[bar"]}

print("Special characters in property values passed!")
'

python3 -c '
from sgf_parsing import parse, SgfTree

t = parse("(;A[root](;B[b](;C[c])(;D[d]))(;E[e]))")
assert t.properties == {"A": ["root"]}
assert len(t.children) == 2
b = t.children[0]
assert b.properties == {"B": ["b"]}
assert len(b.children) == 2
assert b.children[0].properties == {"C": ["c"]}
assert b.children[1].properties == {"D": ["d"]}
e = t.children[1]
assert e.properties == {"E": ["e"]}
assert len(e.children) == 0

print("Deep variation tree passed!")
'

